984	impl RecordSink for StreamSink {
985	    fn record_bytes(&mut self, bytes: &[u8]) {
986	        self.leaf.update(bytes);
987	    }
988	
989	    fn record_end(&mut self) {
990	        // Fires once per LF, so a leading or consecutive LF folds the empty
991	        // record between them.
992	        self.finish_record();
993	    }
994	
995	    fn tail_end(&mut self) {
996	        // Content after the last LF: the same fold as an LF termination.
997	        self.finish_record();
998	    }
999	}
