1684	    fn parse_proof_rejects_missing_fields_and_empty_or_wrong_container() {
1685	        let refs: Vec<&[u8]> = vec![b"a", b"b"];
1686	        let (root, path) = root_and_path(&refs, 0);
1687	        let full = valid_proof_bytes(2, 0, &root, &path);
1688	        assert!(parse_proof(&full).is_ok());
1689	
1690	        let drop_field = |bytes: &[u8], needle: &str| -> Vec<u8> {
1691	            let text = String::from_utf8(bytes.to_vec()).unwrap();
1692	            // Rebuild without the named member by string surgery on the
1693	            // canonical compact form emitted by proof_json.
1694	            let idx = text.find(needle).unwrap();
1695	            let mut end = idx + needle.len();
1696	            // Consume through the member's value terminator.
1697	            match needle {
1698	                "\"tree_size\":" | "\"leaf_index\":" => {
1699	                    while end < text.len()
1700	                        && text.as_bytes()[end] != b','
1701	                        && text.as_bytes()[end] != b'}'
1702	                    {
1703	                        end += 1;
1704	                    }
1705	                }
1706	                "\"root\":" => {
1707	                    while end < text.len() && text.as_bytes()[end] != b'"' {
1708	                        end += 1;
1709	                    }
1710	                    end += 1;
1711	                }
1712	                _ => {
1713	                    end = text.rfind(']').unwrap() + 1;
1714	                }
1715	            }
1716	            let mut s = String::new();
1717	            s.push_str(&text[..idx]);
1718	            let rest = &text[end..];
1719	            // Tidy the separator left by the removed member.
1720	            if rest.starts_with(',') {
1721	                s.push_str(&rest[1..]);
1722	            } else if text[..idx].ends_with(',') {
1723	                s.pop();
1724	                s.push_str(rest);
1725	            } else {
1726	                s.push_str(rest);
1727	            }
1728	            s.into_bytes()
1729	        };
1730	
1731	        for key in ["\"tree_size\":", "\"leaf_index\":", "\"root\":", "\"audit_path\":"] {
1732	            let cut = drop_field(&full, key);
1733	            assert!(parse_proof(&cut).is_err(), "proof missing {key} must be invalid: {cut:?}");
1734	        }
1735	
1736	        for bad in [
1737	            b"".as_slice(),
1738	            b"   ",
1739	            b"null",
1740	            b"[]",
1741	            b"\"x\"",
1742	            b"123",
1743	            b"{}",
1744	            b"[{\"tree_size\":1}]",
1745	        ] {
1746	            assert!(parse_proof(bad).is_err(), "{bad:?} must not parse as a proof");
1747	        }
1748	    }
