108	        );
109	    }
110	
111	    let stdout = &output.stdout;
112	    if stdout.len() != 65 || stdout[64] != b'\n' {
113	        panic!(
114	            "[{desc}] stdout is not exactly 64 hex digits + LF for sequence {sequence:?}: {stdout:?}"
115	        );
116	    }
