/// 直接在内存中生成成员证明失败的分类。
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ProveError {
    /// 请求的位置在批次中不存在：序号达到或超过记录数。空批次（零条记录）
    /// 对任何序号都报这一类错误，而不是产生一份“空树成员证明”。附带
    /// `requested_index`（调用方请求的序号，完整保留 64 位含义）与
    /// `record_count`（批次实际记录数）。
    PositionNotFound {
        /// 调用方请求的从 0 开始的记录序号。
        requested_index: u64,
        /// 批次实际包含的记录数。
        record_count: u64,
    },
    /// 批次记录数超过本平台可直接物化的范围：无法在内存中索引的记录数
    /// （大于 [`usize::MAX`]）。证明所需的树大小仍是合法的 64 位整数；
    /// 需要这么大的树时可改用合成/流式方式，成员“核验”不受此限制。
    BatchTooLarge(u64),
}

impl fmt::Display for ProveError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ProveError::PositionNotFound {
                requested_index,
                record_count,
            } => {
                if *record_count == 0 {
                    write!(
                        f,
                        "record index {requested_index} does not exist: the batch holds zero records"
                    )
                } else {
                    write!(
                        f,
                        "record index {requested_index} does not exist: batch holds {record_count} record(s), valid indices are 0 through {}",
                        record_count - 1
                    )
                }
            }
            ProveError::BatchTooLarge(count) => {
                write!(
                    f,
                    "batch of {count} record(s) is too large to materialize on this platform (usize::MAX = {})",
                    usize::MAX
                )
            }
        }
    }
}

