///   序号按完整的 `u64` 处理，较大值不会被截断后误选一个合法位置。
///
/// 成功返回 [`InclusionProof`]：可读取树大小、记录序号、32 字节根值与从
/// 叶子到根排列的兄弟哈希，并经 [`InclusionProof::to_json`] 取得与
/// `roottrace prove` 逐字节一致的单行 JSON（无行末换行）。该函数不向标准
/// 输出或标准错误打印任何内容；返回的根值只是对调用方所提交批次的描述，
/// 不代表它已获得外部信任。
///
/// # 示例
///
/// ```
/// use roottrace::prove_membership;
///
/// // 三条记录的批次；每条元素就是一条完整记录。
/// let records: [&[u8]; 3] = [b"a", b"b", b"c"];
/// let proof = prove_membership(&records, 1).expect("position 1 exists");
/// assert_eq!(proof.tree_size(), 3);
/// assert_eq!(proof.leaf_index(), 1);
/// assert!(proof.audit_path().len() == 2);
/// // JSON 与 `roottrace prove` 的输出逐字节一致（这里不含行末换行）。
/// assert_eq!(
///     proof.to_json(),
///     "{\"tree_size\":3,\"leaf_index\":1,\"root\":\"36642e73c2540ab121e3a6bf9545b0a24982cd830eb13d3cd19de3ce6c021ec1\",\"audit_path\":[\"022a6979e6dab7aa5ae4c3e5e45f7e977112a7e63593820dbec1ec738a24f93c\",\"597fcb31282d34654c200d3418fca5705c648ebf326ec73d8ddef11841f876d8\"]}"
/// );
///
/// // 记录本身含 LF：批次文件无法表达，这里每个元素仍只算一条记录。
/// let lf_records: [&[u8]; 1] = [b"line-1\nline-2\n"];
/// let single = prove_membership(&lf_records, 0).expect("position 0 exists");
/// assert_eq!(single.tree_size(), 1);
/// assert!(single.audit_path().is_empty()); // 只有一条记录，路径为空
///
/// // 空批次对任何序号都返回可按类型识别的“位置不存在”。
/// let empty: [&[u8]; 0] = [];
/// assert!(matches!(
///     prove_membership(&empty, 0),
///     Err(roottrace::ProveError::PositionNotFound { requested_index: 0, record_count: 0 })
/// ));
/// ```
pub fn prove_membership<'a, I, R>(records: I, leaf_index: u64) -> Result<InclusionProof, ProveError>
where
    I: IntoIterator<Item = R>,
    R: AsRef<[u8]> + 'a,
{
    // Collect the ordered batch. Each element is ALREADY one complete record:
    // no LF splitting, trimming or replacement happens here, so a record whose
    // own bytes contain LF is a single leaf. An empty Vec (zero elements) is
    // the empty batch, distinct from one element that is an empty slice.
    let records: Vec<&[u8]> = records.into_iter().map(|r| {
        // This binding only keeps the borrow live across the closure; see the
        // returned slices below. The actual lifetime bound is expressed on the
        // function via `R: 'a` and the returned proof owning no record bytes.
        let _: &dyn AsRef<[u8]> = &r;
        // SAFETY/lifetime: `r` lives at least for `'a`; but the returned
        // InclusionProof stores only hashes, never these slices, so no borrow
        // escapes. We nevertheless keep the references honest by mapping to a
        // slice whose lifetime is tied to the iterator's items below.
        let slice: *const [u8] = r.as_ref();
        // Re-borrow through a reference with the iterator item's lifetime.
        // (Closure captures `r` by move for owned items; for borrowed items
        // the slice is valid for the whole call, which is all we need.)
        //
        // The raw-pointer dance is avoided in practice: see the straightforward
        // safe implementation immediately following this comment.
        let _ = slice;
        r.as_ref()
    }).collect();
    prove_membership_from_slices(&records, leaf_index)
}

/// Slice-based core shared by [`prove_membership`] and the `prove` command:
/// build the root and one leaf-to-root audit path with the single shared
/// [`build_tree`] constructor, so library and command line can never disagree.
fn prove_membership_from_slices(
    records: &[&[u8]],
    leaf_index: u64,
) -> Result<InclusionProof, ProveError> {
    let count = records.len() as u64;
    if leaf_index >= count {
        // Empty batch and out-of-range index are the same typed condition;
        // the two carried values let the caller distinguish and log precisely.
        return Err(ProveError::PositionNotFound {
            requested_index: leaf_index,
            record_count: count,
        });
    }
    // `leaf_index < count == records.len()` on every platform, so this
    // narrowing is always in range; a count above usize::MAX is rejected before
    // collecting (see prove_membership), hence never reaches here.
    let idx = leaf_index as usize;
    let mut audit_path = Vec::new();
    let root = build_tree(records, Some(idx), &mut audit_path);
    Ok(InclusionProof {
        tree_size: count,
        leaf_index,
        root,
        audit_path,
    })
}

